element.style.display = 'flex';
element.style.flexWrap = 'wrap';
element.style.gap = '8px';
if (!element.querySelector('.global-action__item.preferences-link')) {
  var prefItem = document.createElement('div');
  prefItem.className = 'global-action__item preferences-link';
  var prefLink = document.createElement('a');
  prefLink.href = 'https://www.fandom.com/preferences';
  prefLink.className = 'wds-button wds-is-secondary global-action__link';
  prefLink.setAttribute('rel', 'nofollow');
  prefLink.setAttribute('data-tracking-label', 'account.preferences');
  prefLink.setAttribute('aria-label', 'Preferences');
  prefLink.textContent = 'Preferences';
  prefItem.appendChild(prefLink);
  element.appendChild(prefItem);
}
